CREATE TABLE IF NOT EXISTS members (id TEXT PRIMARY KEY, first_name TEXT NOT NULL, last_name TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending', expires_at TEXT NOT NULL DEFAULT '', token TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, id_number TEXT UNIQUE, date_of_birth TEXT, place_of_birth TEXT, membership_location TEXT, gender TEXT, password_salt TEXT NOT NULL DEFAULT '', password_hash TEXT NOT NULL DEFAULT '', password_must_change BOOLEAN NOT NULL DEFAULT FALSE);
ALTER TABLE members ADD COLUMN IF NOT EXISTS password_salt TEXT NOT NULL DEFAULT '';
ALTER TABLE members ADD COLUMN IF NOT EXISTS password_hash TEXT NOT NULL DEFAULT '';
ALTER TABLE members ADD COLUMN IF NOT EXISTS password_must_change BOOLEAN NOT NULL DEFAULT FALSE;
CREATE UNIQUE INDEX IF NOT EXISTS idx_members_email ON members (lower(email));
CREATE TABLE IF NOT EXISTS promos (code TEXT PRIMARY KEY, campaign TEXT NOT NULL, member_id TEXT, status TEXT NOT NULL DEFAULT 'available', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS updates (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payments (id TEXT PRIMARY KEY, member_id TEXT NOT NULL, amount INTEGER NOT NULL DEFAULT 200, receipt_key TEXT NOT NULL, receipt_name TEXT NOT NULL, receipt_type TEXT NOT NULL, reference TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'submitted', note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, reviewed_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS fixtures (id TEXT PRIMARY KEY, opponent TEXT NOT NULL, kickoff TEXT NOT NULL, venue TEXT NOT NULL, home_away TEXT NOT NULL, competition TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'upcoming', rollers_score INTEGER, opponent_score INTEGER, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS standings (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, team TEXT NOT NULL UNIQUE, played INTEGER NOT NULL DEFAULT 0, won INTEGER NOT NULL DEFAULT 0, drawn INTEGER NOT NULL DEFAULT 0, lost INTEGER NOT NULL DEFAULT 0, goal_difference INTEGER NOT NULL DEFAULT 0, points INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS club_updates (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS member_notifications (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, member_id TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, reply TEXT NOT NULL DEFAULT '', replied_at TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS players (id TEXT PRIMARY KEY, first_name TEXT NOT NULL, last_name TEXT NOT NULL, squad_number INTEGER NOT NULL UNIQUE, position TEXT NOT NULL, contract_type TEXT NOT NULL DEFAULT 'Permanent', contract_start TEXT NOT NULL DEFAULT '', contract_end TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'active', lineup_role TEXT NOT NULL DEFAULT 'squad', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS club_settings (id INTEGER PRIMARY KEY, membership_validity_days INTEGER NOT NULL DEFAULT 334, expiry_reminder_days INTEGER NOT NULL DEFAULT 7, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admin_users (email TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', role TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, pin_salt TEXT NOT NULL DEFAULT '', pin_hash TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admin_sessions (token_hash TEXT PRIMARY KEY, email TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admin_login_attempts (email TEXT PRIMARY KEY, failed_count INTEGER NOT NULL DEFAULT 0, locked_until TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS member_sessions (token_hash TEXT PRIMARY KEY, member_id TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS member_login_attempts (email TEXT PRIMARY KEY, failed_count INTEGER NOT NULL DEFAULT 0, locked_until TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL);
